def _kernel(q, name):
    """Dimensionless 3D kernels, with yt's support radius h (Price's 2h)."""
    q = np.asarray(q)
    if name == "cubic":
        value = np.where(q < 0.5, 1 - 6 * q**2 + 6 * q**3, 2 * (1 - q) ** 3)
        value *= 8 / np.pi
    elif name == "wendland2":
        value = 21 / (2 * np.pi) * (1 - q) ** 4 * (1 + 4 * q)
    else:
        raise ValueError(name)
    return np.where(q < 1, value, 0)


def _projected_kernel(q, name):
    # Integrate the scientific definition independently of yt's lookup table.
    nodes, weights = np.polynomial.legendre.leggauss(200)
    extent = np.sqrt(np.maximum(1 - q**2, 0))
    radii = np.sqrt(q[:, None] ** 2 + (extent[:, None] * nodes) ** 2)
    return extent * (_kernel(radii, name) @ weights)


def _particles(dtype=np.float64):
    return {
        "particle_position": (
            np.array([[0.03, -0.01, 0.08], [-0.07, 0.05, -0.04],
                      [0, 0, 0], [0.3, 0.15, 0.2]], dtype=dtype),
            "cm",
        ),
        "particle_mass": (np.array([0.7, 1.2, 0.4, 0.6], dtype=dtype), "g"),
        "density": (np.array([2.1, 0.6, 1.8, 0.9], dtype=dtype), "g/cm**3"),
        "smoothing_length": (np.array([0.13, 0.29, 0.20, 0.23], dtype=dtype), "cm"),
