def _load(data, kernel="cubic", length_unit=1, periodicity=(False,) * 3):
    ds = yt.load_particles(
        data, length_unit=length_unit, mass_unit=2.5,
        bbox=np.array([[-1, 1]] * 3) / length_unit, periodicity=periodicity,
    )
    ds.kernel_name = kernel
    return ds


def _reference(data, normal, kernel, weight=False, moment=1):
    pos, mass, density, hsml, quantity = (
        np.asarray(data[key][0], dtype=np.float64)
        for key in ("particle_position", "particle_mass", "density",
                    "smoothing_length", "temperature")
    )
    normal = np.asarray(normal, dtype=np.float64)
    normal /= np.linalg.norm(normal)
    impact = np.linalg.norm(pos - np.outer(pos @ normal, normal), axis=1)
    volume_kernel = mass / density / hsml**2 * _projected_kernel(impact / hsml, kernel)
    if not weight:
        return np.sum(volume_kernel * quantity)
    weights = volume_kernel * density
    mean = np.sum(weights * quantity) / np.sum(weights)
    if moment == 1:
        return mean
    return np.sqrt(np.sum(weights * (quantity - mean) ** 2) / np.sum(weights))


