        pos = data["particle_position"][0] + offset - center
        wk = mass / density / hsml**3 * _kernel(np.linalg.norm(pos, axis=1) / hsml, "cubic")
        numerator += np.sum(wk * quantity)
        denominator += np.sum(wk)
    expected = numerator / denominator if normalize else numerator
    slc = ds.slice(2, center[2]).to_frb(
        (0.08, "cm"), (3, 5), center=ds.arr(center, "cm"), periodic=True,
    )
    assert_allclose(slc["gas", "temperature"].to_value("K")[2, 1], expected, rtol=2e-12)
    grid = ds.arbitrary_grid(center - 0.04, center + 0.04, [3, 5, 7])
    assert_allclose(grid["gas", "temperature"].to_value("K")[1, 2, 3], expected, rtol=2e-12)


